// STEP 6 — test suite: unified result normalization
// We test the PURE normalizer that maps raw SDK responses to UnifiedResult.
// No PaymentClient is constructed, so there is no network call.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { types } from 'hyperswitch-prism';
import { normalizeAuthorize } from '../src/library/unified-payments.js';

test('CHARGED is a successful (ok) result', () => {
  const r = normalizeAuthorize('stripe', {
    status: types.PaymentStatus.CHARGED,
    connectorTransactionId: 'txn_123',
  });
  assert.equal(r.ok, true);
  assert.equal(r.transactionId, 'txn_123');
  assert.equal(r.statusText, 'CHARGED');
  assert.equal(r.error, undefined);
});

test('AUTHORIZED is also ok (auth without capture)', () => {
  const r = normalizeAuthorize('adyen', { status: types.PaymentStatus.AUTHORIZED });
  assert.equal(r.ok, true);
});

test('FAILURE is not ok and surfaces the connector error message', () => {
  const r = normalizeAuthorize('stripe', {
    status: types.PaymentStatus.FAILURE,
    error: { connectorDetails: { message: 'card declined' } },
  });
  assert.equal(r.ok, false);
  assert.equal(r.error, 'card declined');
});

test('PENDING is flagged pending and not treated as ok', () => {
  const r = normalizeAuthorize('cybersource', { status: types.PaymentStatus.PENDING });
  assert.equal(r.ok, false);
  assert.equal(r.pending, true);
});

test('carries the PSP name through unchanged', () => {
  const r = normalizeAuthorize('adyen', { status: types.PaymentStatus.CHARGED });
  assert.equal(r.psp, 'adyen');
  assert.equal(r.operation, 'authorize');
});

// STEP 6 — test suite: payment retry / fallback
// We drive withRetry() with FAKE attempt functions so we can assert the
// orchestration logic precisely, with zero network calls.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { withRetry, buildPlan, type AttemptOutcome } from '../src/orchestrator/retry.js';
import type { PspName } from '../config/psp-registry.js';

const fail = (statusText = 'FAILURE'): AttemptOutcome => ({ ok: false, statusText, error: 'declined' });
const pass = (statusText = 'CHARGED'): AttemptOutcome => ({ ok: true, statusText });

test('stops at the first successful PSP', async () => {
  const tried: PspName[] = [];
  const res = await withRetry({
    plan: ['stripe', 'adyen', 'cybersource'],
    attempt: async (psp) => {
      tried.push(psp);
      return psp === 'adyen' ? pass() : fail();
    },
  });
  assert.equal(res.succeeded, true);
  assert.equal(res.winningPsp, 'adyen');
  assert.deepEqual(tried, ['stripe', 'adyen']); // never reached cybersource
  assert.equal(res.attempts.length, 2);
});

test('returns failure after exhausting every PSP', async () => {
  const res = await withRetry({
    plan: ['stripe', 'adyen'],
    attempt: async () => fail(),
  });
  assert.equal(res.succeeded, false);
  assert.equal(res.winningPsp, null);
  assert.equal(res.attempts.length, 2);
  assert.equal(res.finalResult?.ok, false);
});

test('succeeds immediately when the first PSP approves', async () => {
  let calls = 0;
  const res = await withRetry({
    plan: ['stripe', 'adyen', 'cybersource'],
    attempt: async () => {
      calls++;
      return pass();
    },
  });
  assert.equal(calls, 1);
  assert.equal(res.winningPsp, 'stripe');
});

test('maxAttempts caps the number of tries', async () => {
  let calls = 0;
  const res = await withRetry({
    plan: ['stripe', 'adyen', 'cybersource'],
    maxAttempts: 2,
    attempt: async () => {
      calls++;
      return fail();
    },
  });
  assert.equal(calls, 2);
  assert.equal(res.attempts.length, 2);
});

test('onAttempt fires once per attempt with the right index', async () => {
  const seen: Array<[PspName, number]> = [];
  await withRetry({
    plan: ['stripe', 'adyen'],
    attempt: async () => fail(),
    onAttempt: (psp, i) => seen.push([psp, i]),
  });
  assert.deepEqual(seen, [['stripe', 0], ['adyen', 1]]);
});

test('buildPlan puts primary first and de-duplicates', () => {
  assert.deepEqual(buildPlan('adyen', ['stripe', 'adyen', 'cybersource']), ['adyen', 'stripe', 'cybersource']);
});

// Runtime processor credentials (control-plane "layer in a processor" support).
// ─────────────────────────────────────────────────────────────────────────────
// The PSP registry reads credentials from process.env LAZILY — every
// isConfigured()/buildConfig() call re-reads process.env. So to enable a processor
// at runtime we simply set its env vars here, and the registry (and therefore the
// store's checkout) picks them up immediately, with no registry changes.
//
// This is in-memory only: overrides live in process.env for the life of the
// process and reset on restart. For persistence, put the keys in .env instead.
// Secrets are NEVER returned to the client — only a per-key "is it set?" boolean.
// ─────────────────────────────────────────────────────────────────────────────

import { getPsp, type PspName } from '../../config/psp-registry.js';

// Matches the registry's own notion of "configured": present and not a placeholder.
function isRealValue(v: string | undefined): boolean {
  const s = (v ?? '').trim();
  return s.length > 0 && !s.startsWith('your_') && !s.startsWith('sk_test_your');
}

// Apply credential values for a processor. Only keys that belong to that processor
// are accepted; an empty value clears the key.
export function setProcessorCredentials(name: PspName, values: Record<string, unknown>): void {
  const allowed = new Set(getPsp(name).envKeys);
  for (const [key, raw] of Object.entries(values)) {
    if (!allowed.has(key)) continue;
    const value = String(raw ?? '').trim();
    if (value) process.env[key] = value;
    else delete process.env[key];
  }
}

// Per-key status for a processor — the value itself is never exposed.
export function credentialStatus(name: PspName): Array<{ key: string; set: boolean }> {
  return getPsp(name).envKeys.map((key) => ({ key, set: isRealValue(process.env[key]) }));
}

// undici compatibility shim — lets the workshop run on Node 23+ (not just 18–22).
// ─────────────────────────────────────────────────────────────────────────────
// The hyperswitch-prism SDK builds an HTTP dispatcher from its bundled **undici@6**
// and hands it to the **global** `fetch()` (see the SDK's dist/src/http_client.js:
// `fetch(url, { …, dispatcher })`). That only works when the runtime's built-in
// fetch is ALSO undici 6 — i.e. Node 18/20/22. Node 23+ bundles undici 7, whose
// Dispatcher handler interface changed, so the v6 dispatcher is rejected with
// `UND_ERR_INVALID_ARG: invalid onError method` and every connector call fails as
// "Network Error: fetch failed".
//
// Fix: when the runtime's built-in undici is NOT v6, replace the global fetch (and
// its companions) with undici@6's own — the same major the SDK's dispatcher targets
// — so the two line up again. Node's built-in undici is simply bypassed for these
// calls. This is a SIDE-EFFECT module: it must run before the first payment call, so
// `unified-payments.ts` imports it as its very first import. It is a NO-OP on Node
// 18–22 (built-in undici already v6).
//
// Long-term this belongs upstream (the SDK should call its own `undici.fetch`, or
// support undici 7). When it does, delete this file and its single import.
// ─────────────────────────────────────────────────────────────────────────────

import * as undici from 'undici';

const builtinUndiciMajor = Number((process.versions.undici ?? '').split('.')[0]);

if (builtinUndiciMajor !== 6) {
  // Built-in fetch is undici 7+ (or absent) — swap in undici@6's fetch stack so it
  // matches the SDK's v6 dispatcher. Keep Headers/Request/Response/FormData from the
  // same undici so instances passed between them stay compatible.
  const g = globalThis as unknown as Record<string, unknown>;
  g.fetch = undici.fetch;
  g.Headers = undici.Headers;
  g.Request = undici.Request;
  g.Response = undici.Response;
  if (undici.FormData) g.FormData = undici.FormData;

  if (process.env.PRISM_TRACE !== 'off') {
    console.error(
      `[undici-compat] Node ${process.versions.node} bundles undici ${process.versions.undici}; ` +
        `patched global fetch to undici@6 for hyperswitch-prism SDK compatibility.`,
    );
  }
}

/**
 * Adyen SDK Handler
 * Uses Adyen Web Components v6.31.1 with Sessions Flow
 * Reference: https://docs.adyen.com/online-payments/build-your-integration
 *
 * Sessions Flow handles the complete payment client-side:
 * - No manual tokenization needed
 * - No server-side authorization call needed
 * - Payment is authorized within the Adyen component
 */

let adyenCheckout = null;
let cardComponent = null;
let paymentResolve = null;
let paymentReject = null;

/**
 * Initialize Adyen Checkout with Sessions Flow
 *
 * @param {Object} session - Session object from server { id, sessionData }
 * @param {string} session.id - Session ID from /sessions call
 * @param {string} session.sessionData - Session data from /sessions call
 * @param {string} clientKey - Adyen client key for client-side authentication
 * @param {Object} config - Payment configuration
 * @param {number} config.amount - Amount in minor units (e.g., 1000 for $10.00)
 * @param {string} config.currency - Currency code (e.g., 'USD', 'EUR')
 * @param {string} config.countryCode - Country code (e.g., 'US', 'NL')
 * @param {string} config.locale - Locale for UI (e.g., 'en-US')
 * @returns {Promise<void>}
 */
async function initAdyen(session, clientKey, config) {
  try {
    // Adyen SDK v6+ exposes AdyenCheckout and components on window.AdyenWeb
    let AdyenCheckout, Card;
    if (window.AdyenWeb) {
      AdyenCheckout = window.AdyenWeb.AdyenCheckout;
      Card = window.AdyenWeb.Card;
    } else if (typeof window.AdyenCheckout === 'function') {
      AdyenCheckout = window.AdyenCheckout;
    } else {
      throw new Error('Adyen Web SDK not loaded properly. Make sure the script tag is included and loaded in the HTML.');
    }

    if (!AdyenCheckout) {
      throw new Error('AdyenCheckout not found in SDK');
    }

    // Validate session data
    if (!session.id || !session.sessionData) {
      throw new Error(`Invalid session data: id=${!!session.id}, sessionData=${!!session.sessionData}`);
    }

    // Validate client key
    if (!clientKey) {
      throw new Error('Client key is required. Please check your ADYEN_CLIENT_KEY environment variable.');
    }

    // Build global configuration object as per Adyen docs
    const globalConfiguration = {
      // Session configuration - REQUIRED
      session: {
        id: session.id,
        sessionData: session.sessionData
      },

      // Client key for client-side authentication - REQUIRED
      clientKey: clientKey,

      // Environment - REQUIRED (use 'test' for sandbox, 'live' for production)
      environment: 'test',

      // Amount for Pay Button display - REQUIRED
      amount: {
        value: config.amount,
        currency: config.currency
      },

      // Country code for filtering payment methods - REQUIRED
      countryCode: config.countryCode,

      // Locale for UI language - REQUIRED
      locale: config.locale || 'en-US',

      // Show pay button in component (default: true)
      showPayButton: true,

      // REQUIRED: Called when payment is successfully completed
      onPaymentCompleted: (result, component) => {
        if (paymentResolve) {
          paymentResolve({
            success: true,
            result: result
          });
        }
      },

      // REQUIRED: Called when payment fails
      onPaymentFailed: (result, component) => {
        if (paymentResolve) {
          paymentResolve({
            success: false,
            error: `Payment ${result.resultCode || 'failed'}`,
            result: result
          });
        }
      },

      // OPTIONAL: Called when an error occurs in the component
      onError: (error, component) => {
        // Don't reject on CANCEL - that's a user action
        if (paymentReject && error.name !== 'CANCEL') {
          paymentReject(new Error(error.message));
        }
      }
    };

    adyenCheckout = await AdyenCheckout(globalConfiguration);

    // Create and mount Card Component
    const cardContainer = document.getElementById('adyen-card-container');

    if (!cardContainer) {
      throw new Error('Card container (#adyen-card-container) not found in DOM');
    }

    // Create card component using v6.x API
    if (Card && typeof Card === 'function') {
      try {
        cardComponent = new Card(adyenCheckout, {
          hasHolderName: true,
          holderNameRequired: false,
          enableStoreDetails: false,
          hideCVC: false,
          brands: ['visa', 'mc', 'amex', 'discover']
        });

        cardComponent.mount(cardContainer);
      } catch (err) {
        // Fallback: use createComponent helper
        const createComponent = window.AdyenWeb.createComponent;
        cardComponent = createComponent('card', adyenCheckout, {
          hasHolderName: true,
          holderNameRequired: false,
          enableStoreDetails: false,
          hideCVC: false,
          brands: ['visa', 'mc', 'amex', 'discover']
        });
        cardComponent.mount(cardContainer);
      }
    } else {
      throw new Error('Unable to create Card component: Card class not available');
    }

  } catch (error) {
    console.error('[Adyen] Initialization error:', error);
    throw error;
  }
}

/**
 * Wait for payment completion
 *
 * Sessions Flow handles the complete payment authorization client-side.
 * This function returns a promise that resolves when the payment completes
 * (either successfully or with failure).
 *
 * @returns {Promise<{success: boolean, result?: object, error?: string}>}
 */
function waitForPaymentCompletion() {
  return new Promise((resolve, reject) => {
    paymentResolve = resolve;
    paymentReject = reject;
  });
}

/**
 * Check if Adyen checkout is initialized
 * @returns {boolean}
 */
function isAdyenInitialized() {
  return adyenCheckout !== null && cardComponent !== null;
}

/**
 * Get the card component instance (for advanced operations)
 * @returns {object|null}
 */
function getCardComponent() {
  return cardComponent;
}

/**
 * Submit payment programmatically (if showPayButton is false)
 * Note: Not needed if showPayButton is true (default)
 *
 * @returns {Promise<void>}
 */
async function submitAdyenPayment() {
  if (!cardComponent) {
    throw new Error('Card component not initialized');
  }

  await cardComponent.submit();
}

// Export functions globally for use in checkout.js
window.initAdyen = initAdyen;
window.waitForPaymentCompletion = waitForPaymentCompletion;
window.isAdyenInitialized = isAdyenInitialized;
window.getCardComponent = getCardComponent;
window.submitAdyenPayment = submitAdyenPayment;

/**
 * GlobalPay SDK Handler - NON PCI Compliant
 * Uses GlobalPay Credit Card Form (auto-submit)
 * Reference: /Users/jeeva.ramachandran/Downloads/archive/connector/globalpay.html
 */

let cardForm = null;

/**
 * Initialize GlobalPay Credit Card Form
 * @param {string} accessToken - Access token from server (with PMT_POST_Create_Single permission)
 * @returns {Promise<boolean>}
 */
async function initGlobalPay(accessToken) {
  try {
    // Check if GlobalPayments is loaded
    if (typeof GlobalPayments === 'undefined') {
      throw new Error('GlobalPayments SDK not loaded');
    }

    // Configure GlobalPayments
    GlobalPayments.configure({
      accessToken: accessToken,
      env: 'sandbox'
    });

    // Create the credit card form - auto-mounts to #credit-card
    // This creates hosted fields for card number, expiry, and CVV
    cardForm = GlobalPayments.creditCard.form('#credit-card');

    return true;
  } catch (error) {
    console.error('[GlobalPay] Init error:', error);
    throw error;
  }
}

/**
 * Setup GlobalPay event handlers
 * @param {Function} onTokenSuccess - Callback when token is created
 */
function setupGlobalPayHandlers(onTokenSuccess) {
  if (!cardForm) {
    throw new Error('GlobalPay not initialized');
  }

  const errorElement = document.getElementById('globalpay-error');

  // Handle token success - auto-submitted when user presses Enter or form validates
  cardForm.on('token-success', (resp) => {
    const token = resp.paymentReference;

    if (token) {
      onTokenSuccess(token);
    } else {
      console.error('[GlobalPay] No paymentReference in response:', resp);
      if (errorElement) {
        errorElement.textContent = 'Token creation failed - no payment reference';
      }
    }
  });

  // Handle token error
  cardForm.on('token-error', (err) => {
    console.error('[GlobalPay] Tokenization failed:', err);

    let errorMsg = 'Payment tokenization failed';
    if (err.error_code === 'ACTION_NOT_AUTHORIZED' || err.detailed_error_code === '40022') {
      errorMsg = 'Access token lacks tokenization permissions. Contact GlobalPay support to enable PMT_POST_Create permission.';
    } else if (err.reason || err.detailed_error_description) {
      errorMsg = err.reason || err.detailed_error_description;
    }

    if (errorElement) {
      errorElement.textContent = errorMsg;
    }
  });

  // Global error handler
  GlobalPayments.on('error', (err) => {
    console.error('[GlobalPay] SDK error:', err);
    if (errorElement) {
      errorElement.textContent = err.message || 'An error occurred';
    }
  });
}

// Export globally
window.initGlobalPay = initGlobalPay;
window.setupGlobalPayHandlers = setupGlobalPayHandlers;

/**
 * Stripe SDK Handler
 * Uses Stripe Payment Element for embedded checkout (no redirect)
 */

let stripe = null;
let elements = null;
let currentClientSecret = null;

/**
 * Initialize Stripe with Payment Element
 * @param {string} publishableKey - Stripe publishable key
 * @param {string} clientSecret - Payment Intent client secret from server
 * @returns {Promise<boolean>}
 */
async function initStripe(publishableKey, clientSecret) {
  try {
    if (!publishableKey || !clientSecret) {
      throw new Error('Missing publishable key or client secret');
    }

    stripe = Stripe(publishableKey);
    currentClientSecret = clientSecret;

    // Create Elements instance with manual payment method creation
    elements = stripe.elements({
      clientSecret: clientSecret,
      paymentMethodCreation: 'manual',
      appearance: {
        theme: 'stripe',
        variables: {
          colorPrimary: '#2563eb',
          colorBackground: '#ffffff',
          colorText: '#30313d',
          colorDanger: '#df1b41',
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
          borderRadius: '8px'
        }
      }
    });

    // Create and mount Payment Element
    const paymentElement = elements.create('payment', {
      layout: 'tabs'
    });

    // Check if container exists
    const container = document.getElementById('payment-element');
    if (!container) {
      throw new Error('Payment element container not found');
    }

    paymentElement.mount('#payment-element');

    // Handle load errors
    paymentElement.on('loaderror', (event) => {
      console.error('[Stripe] Element load error:', event);
    });

    // Handle real-time validation errors
    paymentElement.on('change', (event) => {
      const errorElement = document.getElementById('stripe-error');
      if (event.error) {
        errorElement.textContent = event.error.message;
      } else {
        errorElement.textContent = '';
      }
    });

    return true;
  } catch (error) {
    console.error('[Stripe] Init error:', error);
    throw error;
  }
}

/**
 * Submit payment - tokenize card and return payment method
 * @returns {Promise<{success: boolean, error?: string, paymentMethod?: object}>}
 */
async function submitStripePayment() {
  if (!stripe || !elements) {
    throw new Error('Stripe not initialized');
  }

  const submitBtn = document.getElementById('stripe-submit-btn');
  const btnText = document.getElementById('btn-text');
  const btnSpinner = document.getElementById('btn-spinner');
  const errorElement = document.getElementById('stripe-error');

  // Show loading
  submitBtn.disabled = true;
  btnText.textContent = 'Processing...';
  btnSpinner.classList.remove('hidden');
  errorElement.textContent = '';

  try {
    // Submit the form
    const { error: submitError } = await elements.submit();
    if (submitError) {
      throw submitError;
    }

    // Create payment method (tokenize card) - don't confirm yet
    const { paymentMethod, error: createError } = await stripe.createPaymentMethod({
      elements
    });

    if (createError) {
      throw createError;
    }

    // Don't reset button here - let authorizePayment handle it
    return {
      success: true,
      paymentMethod: {
        id: paymentMethod.id,
        type: paymentMethod.type
      }
    };

  } catch (error) {
    console.error('[Stripe] Payment error:', error);
    errorElement.textContent = error.message;
    submitBtn.disabled = false;
    btnText.textContent = 'Pay Now';
    btnSpinner.classList.add('hidden');
    return { success: false, error: error.message };
  }
}

// Export globally
window.initStripe = initStripe;
window.submitStripePayment = submitStripePayment;

// STEP 6 — test suite: condition-based routing
// Pure functions → no network, no credentials. Run with:  npm test
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { selectPsp, DEFAULT_ROUTING_PLAN, type RoutingPlan } from '../src/orchestrator/routing.js';

test('high-value payments route to adyen', () => {
  const d = selectPsp(DEFAULT_ROUTING_PLAN, { minorAmount: 9900, currency: 'USD' });
  assert.equal(d.psp, 'adyen');
});

test('EUR payments route to cybersource', () => {
  const d = selectPsp(DEFAULT_ROUTING_PLAN, { minorAmount: 2000, currency: 'EUR' });
  assert.equal(d.psp, 'cybersource');
});

test('small USD payments fall back to stripe', () => {
  const d = selectPsp(DEFAULT_ROUTING_PLAN, { minorAmount: 1500, currency: 'USD' });
  assert.equal(d.psp, 'stripe');
});

test('first matching rule wins (high-value EUR → adyen, not cybersource)', () => {
  // 9900 (>5000) matches the high-value rule before the EUR rule.
  const d = selectPsp(DEFAULT_ROUTING_PLAN, { minorAmount: 9900, currency: 'EUR' });
  assert.equal(d.psp, 'adyen');
});

test('threshold is exclusive (exactly 5000 is NOT high-value)', () => {
  const d = selectPsp(DEFAULT_ROUTING_PLAN, { minorAmount: 5000, currency: 'USD' });
  assert.equal(d.psp, 'stripe');
});

test('custom plans are honored', () => {
  const plan: RoutingPlan = {
    rules: [{ reason: 'GBP → adyen', when: (c) => c.currency === 'GBP', use: 'adyen' }],
    fallback: 'cybersource',
  };
  assert.equal(selectPsp(plan, { minorAmount: 100, currency: 'GBP' }).psp, 'adyen');
  assert.equal(selectPsp(plan, { minorAmount: 100, currency: 'USD' }).psp, 'cybersource');
});

// WORKSHOP STEPS 1–2 — run a payment, then switch the PSP   (CLI-WALKTHROUGH.md)
// ─────────────────────────────────────────────────────────────────────────────
//   Step 1: run this with the default PSP   ->  npm run run:payment
//           (read the output — that's the normalized "payment experience")
//   Step 2: open config/active-psp.ts, change ACTIVE_PSP 'stripe' -> 'adyen'
//           (one line), then run it again    ->  npm run run:payment
//
// Notice the application code here does NOT change between steps 1 and 2. The
// unified library makes the processor an interchangeable detail.
// ─────────────────────────────────────────────────────────────────────────────

import 'dotenv/config';

import { ACTIVE_PSP } from '../../config/active-psp.js';
import { getPsp } from '../../config/psp-registry.js';
import { authorize, refund } from '../library/unified-payments.js';
import { APPROVED_CARD, type Order } from '../library/cards.js';
import { banner, step, money } from '../library/format.js';

async function main() {
  const psp = getPsp(ACTIVE_PSP);

  banner(`Running a payment through PSP: ${psp.displayName}  (ACTIVE_PSP = '${ACTIVE_PSP}')`);

  if (!psp.isConfigured()) {
    step(
      `No sandbox credentials found for ${psp.displayName} ` +
        `(expected env: ${psp.envKeys.join(', ')}).`,
    );
    step('The request will still be built and sent — expect a connector auth error.');
    step('Add your keys to .env to see a real approval. Continuing anyway...\n');
  }

  const order: Order = {
    merchantTransactionId: `workshop_${Date.now()}`,
    minorAmount: 1000, // $10.00
    currency: 'USD',
    card: APPROVED_CARD,
  };

  // ── Authorize + capture (one step) ─────────────────────────────────────────
  step(`Authorizing ${money(order.minorAmount, order.currency)} on card ****${order.card.cardNumber.slice(-4)} ...`);
  const auth = await authorize(ACTIVE_PSP, order);

  console.log(`    → status      : ${auth.statusText} (${auth.status})`);
  console.log(`    → transaction : ${auth.transactionId ?? '—'}`);
  if (auth.error) console.log(`    → error       : ${auth.error}`);

  if (!auth.ok || !auth.transactionId) {
    banner(`Payment not approved by ${psp.displayName}. (See error above.)`);
    return;
  }

  // ── Refund the payment we just made ────────────────────────────────────────
  // Note: the refund flow ships DISABLED (a workshop exercise — see the stub in
  // src/library/unified-payments.ts). Until it's enabled, this reports NOT_ENABLED.
  step(`Refunding ${money(order.minorAmount, order.currency)} for ${auth.transactionId} ...`);
  const ref = await refund(ACTIVE_PSP, order, auth.transactionId);
  console.log(`    → refund status : ${ref.statusText} (${ref.status})`);
  if (ref.error) console.log(`    → note          : ${ref.error}`);

  if (ref.statusText === 'NOT_ENABLED') {
    banner(`Authorize succeeded. Refund is not enabled yet — turn it on during the workshop.`);
  } else {
    banner(`Done. PSP '${ACTIVE_PSP}' handled the full authorize → refund lifecycle.`);
  }
}

main().catch((e) => {
  console.error('Fatal:', e);
  process.exit(1);
});

// The unified payment library
// ─────────────────────────────────────────────────────────────────────────────
// This is the heart of the workshop. Every demo talks to PSPs through these few
// functions and NEVER mentions a specific processor. Swapping Stripe for Adyen
// changes nothing here — only the PSP name passed in.
//
// Each call returns a normalized `UnifiedResult` regardless of which processor
// ran or whether it succeeded, declined, or errored. The orchestrator (routing
// + retry) is built entirely on top of these results.
// ─────────────────────────────────────────────────────────────────────────────

// MUST be first: patches the global fetch on Node 23+ so the SDK's undici@6
// dispatcher works. No-op on Node 18–22. See ./undici-compat.ts.
import './undici-compat.js';

import {
  PaymentClient,
  MerchantAuthenticationClient,
  types,
  IntegrationError,
  ConnectorError,
  NetworkError,
} from 'hyperswitch-prism';

import { getPsp, type PspName } from '../../config/psp-registry.js';
import { toSdkCard, toSdkCurrency, type Order } from './cards.js';
import { paymentStatusText, refundStatusText } from './format.js';
import { tracePrism } from './prism-trace.js';

export interface UnifiedResult {
  ok: boolean; // approved / authorized / charged (a usable success)
  psp: PspName;
  operation: 'authorize' | 'capture' | 'refund' | 'void';
  status: number;
  statusText: string;
  transactionId?: string;
  pending?: boolean;
  error?: string;
}

// Statuses we treat as a usable success for a one-step (auto-capture) payment.
const APPROVED_PAYMENT_STATUSES = new Set<number>([
  types.PaymentStatus.CHARGED,
  types.PaymentStatus.AUTHORIZED,
  types.PaymentStatus.PARTIAL_CHARGED,
]);

const PENDING_PAYMENT_STATUSES = new Set<number>([
  types.PaymentStatus.PENDING,
  types.PaymentStatus.AUTHENTICATION_PENDING,
  types.PaymentStatus.CAPTURE_INITIATED,
]);

// `response.error` is a protobuf object, not plain JSON. Pull out the message.
function extractError(error: any): string | undefined {
  if (!error) return undefined;
  return (
    error?.unifiedDetails?.message ||
    error?.issuerDetails?.message ||
    error?.connectorDetails?.message ||
    error?.message ||
    'Unknown connector error'
  );
}

// Turn any thrown SDK error into a normalized failed result. This lets the
// orchestrator reason about "did it work?" uniformly without try/catch
// scattered everywhere.
function errorToResult(
  psp: PspName,
  operation: UnifiedResult['operation'],
  e: unknown,
): UnifiedResult {
  let error = 'Unexpected error';
  if (e instanceof IntegrationError) error = `IntegrationError: ${e.message}`;
  else if (e instanceof ConnectorError) error = `ConnectorError: ${e.message}`;
  else if (e instanceof NetworkError) error = `NetworkError: ${e.message}`;
  else if (e instanceof Error) error = e.message;
  return { ok: false, psp, operation, status: -1, statusText: 'ERROR', error };
}

// ── Pure normalizer (unit-tested directly, no network) ──────────────────────
export function normalizeAuthorize(psp: PspName, response: any): UnifiedResult {
  const status: number = response?.status ?? -1;
  const ok = APPROVED_PAYMENT_STATUSES.has(status);
  const pending = PENDING_PAYMENT_STATUSES.has(status);
  return {
    ok,
    psp,
    operation: 'authorize',
    status,
    statusText: paymentStatusText(status),
    transactionId: response?.connectorTransactionId ?? undefined,
    pending,
    error: ok ? undefined : extractError(response?.error),
  };
}

// ── Real SDK calls (each returns a UnifiedResult, never throws) ──────────────

export interface AuthorizeOptions {
  // AUTOMATIC = authorize + capture in one call (default).
  // MANUAL    = authorize only; capture later (see capture()).
  captureMethod?: types.CaptureMethod;
}

export async function authorize(
  psp: PspName,
  order: Order,
  opts: AuthorizeOptions = {},
): Promise<UnifiedResult> {
  try {
    const client = new PaymentClient(getPsp(psp).buildConfig());
    const response = await tracePrism({ client: 'PaymentClient', method: 'authorize', psp }, () =>
      client.authorize({
        merchantTransactionId: order.merchantTransactionId,
        amount: { minorAmount: order.minorAmount, currency: toSdkCurrency(order.currency) },
        paymentMethod: { card: toSdkCard(order.card) },
        captureMethod: opts.captureMethod ?? types.CaptureMethod.AUTOMATIC,
        address: {
          billingAddress: {
            countryAlpha2Code: order.currency === 'EUR' ?  types.CountryAlpha2.NL : types.CountryAlpha2.US,
          }
        },
        authType: types.AuthenticationType.NO_THREE_DS,
        returnUrl: 'https://example.com/return',
        // Some processors require these. Including them here keeps the unified
        // request portable across every PSP in the registry (e.g. Cybersource
        // needs customer.email, Adyen needs browserInfo).
        customer: { email: { value: 'jane.workshop@example.com' } },
        browserInfo: {
          colorDepth: 24,
          screenHeight: 900,
          screenWidth: 1440,
          javaEnabled: false,
          javaScriptEnabled: true,
          language: 'en-US',
          timeZoneOffsetMinutes: -480,
          acceptHeader: 'application/json',
          userAgent: 'Mozilla/5.0 (workshop)',
          acceptLanguage: 'en-US,en;q=0.9',
          ipAddress: '1.2.3.4',
        },
      }),
    );
    return normalizeAuthorize(psp, response);
  } catch (e) {
    return errorToResult(psp, 'authorize', e);
  }
}

// ── Tokenized (PCI-compliant) authorization ─────────────────────────────────
// The twin of authorize(): instead of raw card data, it takes a `connectorToken`
// produced client-side by the PSP's own SDK (Stripe Payment Element, Adyen web
// components, GlobalPay hosted fields), so the card never touches our server.
// Notice it still returns a UnifiedResult via the SAME normalizeAuthorize() — the
// orchestrator can't tell whether a payment was raw or tokenized. This is what
// lets the web store offer a "PCI vs non-PCI" toggle over one unified library.
//
// The client session/token bootstrap that produces `connectorToken` is
// connector-specific and lives in the web layer (web/server/sessions.ts); this
// function stays processor-agnostic.
export interface TokenAuthorizeOptions {
  // Some connectors (e.g. GlobalPay) need a server access token passed as state.
  serverAccessToken?: string;
}

export async function tokenAuthorize(
  psp: PspName,
  order: Order,
  connectorToken: string,
  opts: TokenAuthorizeOptions = {},
): Promise<UnifiedResult> {
  try {
    const client = new PaymentClient(getPsp(psp).buildConfig());
    const request: types.PaymentServiceTokenAuthorizeRequest = {
      merchantTransactionId: order.merchantTransactionId,
      amount: { minorAmount: order.minorAmount, currency: toSdkCurrency(order.currency) },
      connectorToken: { value: connectorToken },
      captureMethod: types.CaptureMethod.AUTOMATIC,
      returnUrl: 'https://example.com/return',
      address: {
          billingAddress: {
            countryAlpha2Code: order.currency === 'EUR' ?  types.CountryAlpha2.NL : types.CountryAlpha2.US,
          }
      },
    };
    if (opts.serverAccessToken) {
      request.state = {
        accessToken: { token: { value: opts.serverAccessToken }, tokenType: 'Bearer' },
      };
    }
    const response = await tracePrism({ client: 'PaymentClient', method: 'tokenAuthorize', psp }, () =>
      client.tokenAuthorize(request),
    );
    return normalizeAuthorize(psp, response);
  } catch (e) {
    return errorToResult(psp, 'authorize', e);
  }
}

// Create a client authentication token for a PSP. This is the session bootstrap
// used by the browser-tokenized (PCI) flow: it returns the RAW SDK response and
// leaves connector-specific extraction (Stripe clientSecret, Adyen sessionId,
// etc.) to the caller, keeping this wrapper processor-agnostic.
export async function createClientAuthToken(
  psp: PspName,
  order: Order,
): Promise<types.MerchantAuthenticationServiceCreateClientAuthenticationTokenResponse> {
  const client = new MerchantAuthenticationClient(getPsp(psp).buildConfig());
  return tracePrism({ client: 'MerchantAuthenticationClient', method: 'createClientAuthenticationToken', psp }, () =>
    client.createClientAuthenticationToken({
      merchantClientSessionId: `${order.merchantTransactionId}_session`,
      payment: {
        amount: { minorAmount: order.minorAmount, currency: toSdkCurrency(order.currency) },
      },
    }),
  );
}

export async function capture(
  psp: PspName,
  order: Order,
  connectorTransactionId: string,
): Promise<UnifiedResult> {
  try {
    const client = new PaymentClient(getPsp(psp).buildConfig());
    const response = await tracePrism({ client: 'PaymentClient', method: 'capture', psp }, () =>
      client.capture({
        merchantCaptureId: `${order.merchantTransactionId}_cap`,
        connectorTransactionId,
        amountToCapture: { minorAmount: order.minorAmount, currency: toSdkCurrency(order.currency) },
      }),
    );
    const status: number = response?.status ?? -1;
    const ok =
      status === types.PaymentStatus.CHARGED ||
      status === types.PaymentStatus.PARTIAL_CHARGED ||
      status === types.PaymentStatus.PENDING;
    return {
      ok,
      psp,
      operation: 'capture',
      status,
      statusText: paymentStatusText(status),
      transactionId: connectorTransactionId,
      error: ok ? undefined : extractError(response?.error),
    };
  } catch (e) {
    return errorToResult(psp, 'capture', e);
  }
}

// ★ STEP 5 — "ADD A NEW FLOW" ★  (CLI-WALKTHROUGH.md)
// Void cancels an authorization that has NOT been captured yet. It did not exist
// in the unified library until we added it here — and notice the shape is
// identical to the other flows: build the PSP's PaymentClient, call the matching
// SDK method, normalize the result. That uniformity is what makes the library
// extensible. The SDK already exposes `client.void(...)`; we just surface it.
export async function voidPayment(
  psp: PspName,
  order: Order,
  connectorTransactionId: string,
): Promise<UnifiedResult> {
  try {
    const client = new PaymentClient(getPsp(psp).buildConfig());
    const response = await tracePrism({ client: 'PaymentClient', method: 'void', psp }, () =>
      client.void({
        merchantVoidId: `${order.merchantTransactionId}_void`,
        connectorTransactionId,
      }),
    );
    const status: number = response?.status ?? -1;
    const ok =
      status === types.PaymentStatus.VOIDED ||
      status === types.PaymentStatus.VOID_INITIATED;
    return {
      ok,
      psp,
      operation: 'void',
      status,
      statusText: paymentStatusText(status),
      transactionId: connectorTransactionId,
      error: ok ? undefined : extractError(response?.error),
    };
  } catch (e) {
    return errorToResult(psp, 'void', e);
  }
}

