// WORKSHOP STEP 4 — Payment retry / fallback   (CLI-WALKTHROUGH.md)
// ─────────────────────────────────────────────────────────────────────────────
//   npm run run:retry
//
// We combine BOTH orchestrator use-cases:
//   1. routing picks the primary PSP for the cart
//   2. retry tries the primary first, then falls back to the other PSPs until
//      one approves (or all are exhausted)
//
// The retry engine (withRetry) is pure and processor-agnostic — see
// test/retry.test.ts where we drive it with fakes (success on Nth try, all-fail,
// etc.) and assert it behaves, with zero network calls.
// ─────────────────────────────────────────────────────────────────────────────

import 'dotenv/config';

import { selectPsp, DEFAULT_ROUTING_PLAN } from '../orchestrator/routing.js';
import { withRetry, buildPlan } from '../orchestrator/retry.js';
import { authorize, type UnifiedResult } from '../library/unified-payments.js';
import { getPsp, listPsps } from '../../config/psp-registry.js';
import { APPROVED_CARD, type Order } from '../library/cards.js';
import { banner, step, money } from '../library/format.js';

async function main() {
  const cart = { minorAmount: 7500, currency: 'USD' }; // high-value → routes to adyen

  banner(`Routing + retry for ${money(cart.minorAmount, cart.currency)}`);

  // 1. Route to a primary PSP.
  const decision = selectPsp(DEFAULT_ROUTING_PLAN, cart);
  step(`primary PSP: ${getPsp(decision.psp).displayName}  (${decision.reason})`);

  // 2. Build a fallback plan: primary first, then everyone else.
  const fallbacks = listPsps().filter((p) => p !== decision.psp);
  const plan = buildPlan(decision.psp, fallbacks);
  step(`retry plan: ${plan.map((p) => getPsp(p).displayName).join('  →  ')}\n`);

  const order: Order = {
    merchantTransactionId: `retry_${Date.now()}`,
    minorAmount: cart.minorAmount,
    currency: cart.currency,
    card: APPROVED_CARD,
  };

  // 3. Run the retry loop against the real unified library.
  const outcome = await withRetry<UnifiedResult>({
    plan,
    attempt: (psp) => authorize(psp, { ...order, merchantTransactionId: `${order.merchantTransactionId}_${psp}` }),
    onAttempt: (psp, i, res) => {
      const tag = res.ok ? 'APPROVED' : 'declined/failed';
      console.log(`    attempt ${i + 1} — ${getPsp(psp).displayName}: ${res.statusText} → ${tag}${res.error ? ` (${res.error})` : ''}`);
    },
  });

  if (outcome.succeeded && outcome.winningPsp) {
    banner(`Approved by ${getPsp(outcome.winningPsp).displayName} after ${outcome.attempts.length} attempt(s).`);
  } else {
    banner(`All ${outcome.attempts.length} PSP(s) failed. (Add sandbox credentials in .env to see an approval.)`);
  }
}

main().catch((e) => {
  console.error('Fatal:', e);
  process.exit(1);
});

// Payment retry / fallback (orchestrator use-case B)
// ─────────────────────────────────────────────────────────────────────────────
// Try a payment across an ordered list of PSPs, stopping at the first success.
// This is the classic "if Stripe declines, try Adyen" pattern.
//
// `withRetry` is kept pure and processor-agnostic by accepting an `attempt`
// callback: `(psp) => Promise<AttemptOutcome>`. The real demo passes in our
// `authorize()` wrapper; the tests pass in a fake. That separation is what makes
// the retry logic robust AND unit-testable without a network.
// ─────────────────────────────────────────────────────────────────────────────

import type { PspName } from '../../config/psp-registry.js';

// The minimum shape `withRetry` needs from each attempt's result.
export interface AttemptOutcome {
  ok: boolean;
  statusText: string;
  error?: string;
}

export interface RetryOptions<T extends AttemptOutcome> {
  // PSPs to try, in priority order. First success wins.
  plan: PspName[];
  // How to attempt a payment with a given PSP.
  attempt: (psp: PspName) => Promise<T>;
  // Optional cap on attempts (defaults to the full plan length).
  maxAttempts?: number;
  // Optional hook for logging each attempt (used by the demo).
  onAttempt?: (psp: PspName, index: number, outcome: T) => void;
}

export interface RetryResult<T extends AttemptOutcome> {
  succeeded: boolean;
  finalResult: T | null;
  winningPsp: PspName | null;
  attempts: Array<{ psp: PspName; outcome: T }>;
}

export async function withRetry<T extends AttemptOutcome>(
  opts: RetryOptions<T>,
): Promise<RetryResult<T>> {
  const limit = Math.min(opts.maxAttempts ?? opts.plan.length, opts.plan.length);
  const attempts: Array<{ psp: PspName; outcome: T }> = [];

  for (let i = 0; i < limit; i++) {
    const psp = opts.plan[i];
    const outcome = await opts.attempt(psp);
    attempts.push({ psp, outcome });
    opts.onAttempt?.(psp, i, outcome);

    if (outcome.ok) {
      return { succeeded: true, finalResult: outcome, winningPsp: psp, attempts };
    }
  }

  const last = attempts.length > 0 ? attempts[attempts.length - 1] : null;
  return {
    succeeded: false,
    finalResult: last ? last.outcome : null,
    winningPsp: null,
    attempts,
  };
}

// Build a de-duplicated retry plan that tries `primary` first, then the rest.
// Handy when routing picks the primary PSP and you want the others as fallbacks.
export function buildPlan(primary: PspName, fallbacks: PspName[]): PspName[] {
  const seen = new Set<PspName>();
  const plan: PspName[] = [];
  for (const psp of [primary, ...fallbacks]) {
    if (!seen.has(psp)) {
      seen.add(psp);
      plan.push(psp);
    }
  }
  return plan;
}

// Retry / fallback policy — a control-plane setting.
// ─────────────────────────────────────────────────────────────────────────────
// When enabled, the store's Automatic routing tries the routed processor first and
// then falls back across the other ENABLED processors until one approves (the retry
// orchestrator, src/orchestrator/retry.ts). It only applies to processor-agnostic
// checkout — a browser (PCI) token is pinned to the connector chosen at session time.
//
// In-memory; persisted to web/.control-state.json alongside the plan + enabled set.
// ─────────────────────────────────────────────────────────────────────────────

let enabled = false; // off by default — turn it on in /control to demo retry

export function isRetryEnabled(): boolean {
  return enabled;
}

export function setRetryEnabled(on: boolean): void {
  enabled = Boolean(on);
}

